bool pbs_in_struct(struct pbs_in *ins, /* <=== pbs_in_struct */ 
		   void *struct_ptr, size_t struct_size, struct_desc *sd,
		   struct pbs_in *obj_pbs, struct logger *logger)
{
	uint8_t *cur = ins->cur;
	if (cur + sd->size > ins->roof) {
		log_message(RC_LOG, logger,
			    "not enough room in input packet for %s (remain=%li, sd->size=%zu)",
			    sd->name, (long int)(ins->roof - cur),
			    sd->size);
		return false;
	}

	uint8_t *roof = cur + sd->size; /* may be changed by a length field */
	uint8_t *outp = struct_ptr;
	bool immediate = FALSE;
	uintmax_t last_enum = 0;

	passert(struct_size == 0 || struct_size >= sd->size);

	for (field_desc *fp = sd->fields; fp->field_type != ft_end; fp++) {

		/* field ends within PBS? */
		passert(cur + fp->size <= ins->roof);
		/* field ends within struct? */
		passert(cur + fp->size <= ins->cur + sd->size);
		/* "offset into struct" - "offset into pbs" == "start of struct"? */
		passert(outp - (cur - ins->cur) == struct_ptr);

#if 0
		dbg("%td (%td) '%s'.'%s' %d bytes ",
		    (cur - ins->cur), (cur - ins->start),
		    sd->name, fp->name,
		    fp->size);
#endif

		switch (fp->field_type) {
		case ft_zig: /* should be zero, ignore if not - liberal in what to receive, strict to send */
			for (size_t i = fp->size; i != 0; i--) {
				uint8_t byte = *cur;
				if (byte != 0) {
					/* We cannot zeroize it, it would break our hash calculation. */
					log_message(RC_LOG, logger,
						    "byte at offset %td (%td) of '%s'.'%s' is 0x%02"PRIx8" but should have been zero (ignored)",
						    (cur - ins->cur),
						    (cur - ins->start),
						    sd->name, fp->name,
						    byte);
				}
				cur++;
				*outp++ = '\0'; /* probably redundant */
			}
			break;

		case ft_nat:            /* natural number (may be 0) */
		case ft_len:            /* length of this struct and any following crud */
		case ft_lv:             /* length/value field of attribute */
		case ft_enum:           /* value from an enumeration */
		case ft_loose_enum:     /* value from an enumeration with only some names known */
		case ft_mnpc:
		case ft_pnpc:
		case ft_lss:
		case ft_loose_enum_enum:	/* value from an enumeration with partial name table based on previous enum */
		case ft_af_enum:        /* Attribute Format + value from an enumeration */
		case ft_af_loose_enum:  /* Attribute Format + value from an enumeration */
		case ft_set:            /* bits representing set */
		{
			uintmax_t n = 0;

			/* Reportedly fails on arm, see bug #775 */
			for (size_t i = fp->size; i != 0; i--)
				n = (n << BITS_PER_BYTE) | *cur++;

			switch (fp->field_type) {
			case ft_len:    /* length of this struct and any following crud */
			case ft_lv:     /* length/value field of attribute */
			{
				size_t len = fp->field_type ==
					ft_len ? n :
					immediate ? sd->size :
					n + sd->size;

				if (len < sd->size) {
					log_message(RC_LOG, logger,
						    "%zd-byte %s of %s is smaller than minimum",
						    len,
						    fp->name,
						    sd->name);
					return false;
				}

				if (pbs_left(ins) < len) {
					log_message(RC_LOG, logger,
						    "%zd-byte %s of %s is larger than can fit",
						    len,
						    fp->name,
						    sd->name);
					return false;
				}

				roof = ins->cur + len;
				break;
			}

			case ft_af_loose_enum: /* Attribute Format + value from an enumeration */
			case ft_af_enum: /* Attribute Format + value from an enumeration */
				immediate = ((n & ISAKMP_ATTR_AF_MASK) ==
					     ISAKMP_ATTR_AF_TV);
				last_enum = n & ~ISAKMP_ATTR_AF_MASK;
				/*
				 * Lookup fp->desc using N and
				 * not LAST_ENUM.  Only when N
				 * (value or AF+value) is
				 * found is it acceptable.
				 */
				if (fp->field_type == ft_af_enum &&
				    enum_name(fp->desc, n) == NULL) {
					log_message(RC_LOG, logger,
						    "%s of %s has an unknown value: %s%ju (0x%jx)",
						    fp->name, sd->name,
						    immediate ? "AF+" : "",
						    last_enum, n);
					return false;
				}
				break;

			case ft_enum:   /* value from an enumeration */
				if (enum_name(fp->desc, n) == NULL) {
					log_message(RC_LOG, logger,
						    "%s of %s has an unknown value: %ju (0x%jx)",
						    fp->name, sd->name,
						    n, n);
					return false;
				}
				last_enum = n;
				break;

			case ft_loose_enum:     /* value from an enumeration with only some names known */
			case ft_mnpc:
			case ft_pnpc:
			case ft_lss:
				last_enum = n;
				break;

			case ft_loose_enum_enum:
			{
				/* value from an enumeration with partial name table based on previous enum */
				err_t ugh = enum_enum_checker(sd->name, fp, last_enum);
				if (ugh != NULL) {
					log_message(RC_LOG, logger, "%s", ugh);
					return false;
				}
				break;
			}

			case ft_set:            /* bits representing set */
				if (!testset(fp->desc, n)) {
					log_message(RC_LOG, logger,
						    "bitset %s of %s has unknown member(s): %s (0x%ju)",
						    fp->name, sd->name,
						    bitnamesof(fp->desc, n),
						    n);
					return false;
				}
				break;

			default:
				break;
			}

			/* deposit the value in the struct */
			switch (fp->size) {
			case 8 / BITS_PER_BYTE:
				*(uint8_t *)outp = n;
				break;
			case 16 / BITS_PER_BYTE:
				*(uint16_t *)outp = n;
				break;
			case 32 / BITS_PER_BYTE:
				*(uint32_t *)outp = n;
				break;
			default:
				bad_case(fp->size);
			}
			outp += fp->size;
			break;
		}

		case ft_raw: /* bytes to be left in network-order */
			for (size_t i = fp->size; i != 0; i--)
				*outp++ = *cur++;
			break;

		case ft_end: /* end of field list */
			PASSERT_FAIL("should not be here");

		default:
			bad_case(fp->field_type);
		}
	}

	passert(cur == ins->cur + sd->size);
	if (obj_pbs != NULL) {
		init_pbs(obj_pbs, ins->cur,
			 roof - ins->cur, sd->name);
		obj_pbs->container = ins;
		obj_pbs->desc = sd;
		obj_pbs->cur = cur;
	}
	ins->cur = roof;
	if (DBGP(DBG_BASE)) {
		DBG_prefix_print_struct(ins, "parse ",
					struct_ptr, sd,
					true);
	}
	return true;
}

static err_t enum_enum_checker( /* <=== enum_enum_checker */ 
	const char *struct_name,
	const field_desc *fp,
	uint32_t last_enum)
{
	enum_names *ed = enum_enum_table(fp->desc, last_enum);

	if (ed == NULL) {
		return builddiag("%s of %s has an unknown type: %" PRIu32 " (0x%" PRIx32 ")",
				 fp->name, struct_name,
				 last_enum,
				 last_enum);
	}
	return NULL;
}

static void DBG_prefix_print_struct(const pb_stream *pbs, /* <=== DBG_prefix_print_struct */ 
				    const char *label, const void *struct_ptr,
				    struct_desc *sd, bool len_meaningful)
{
	/* print out a title, with a prefix of asterisks to show
	 * the nesting level.
	 */
	char space[40]; /* arbitrary limit on label+flock-of-* */
	size_t len = strlen(label);

	if (sizeof(space) <= len) {
		DBG_print_struct(label, struct_ptr, sd, len_meaningful);
	} else {
		const pb_stream *p = pbs;
		char *pre = &space[sizeof(space) - (len + 1)];

		strcpy(pre, label);

		/* put at least one * out */
		for (;; ) {
			if (pre <= space)
				break;
			*--pre = '*';
			if (p == NULL)
				break;
			p = p->container;
		}
		DBG_print_struct(pre, struct_ptr, sd, len_meaningful);
	}
}

const struct ip_info *endpoint_type(const ip_endpoint *endpoint) /* <=== endpoint_type */ 
{
	/*
	 * Avoid endpoint*() functions as things quickly get
	 * recursive.
	 */
#if defined(ENDPOINT_TYPE)
	return address_type(&endpoint->address);
#else
	return address_type(endpoint);
#endif
}

bool in_struct(void *struct_ptr, struct_desc *sd, /* <=== in_struct */ 
	       struct pbs_in *ins, struct pbs_in *obj_pbs)
{
	struct logger logger = cur_logger();
	return pbs_in_struct(ins, struct_ptr, 0, sd,
			     obj_pbs, &logger);
}

#define passert(ASSERTION) {						\ /* <=== include/libreswan/passert.h:39:45:passert:1 */ 
		/* wrapping ASSERTION in parens suppresses -Wparen */	\
		bool assertion__ = ASSERTION; /* no parens */		\
		if (!assertion__) {					\
			PASSERT_FAIL("%s", #ASSERTION);			\
		}							\
	}

chunk_t clone_bytes_as_chunk(const void *bytes, size_t sizeof_bytes, const char *name) /* <=== clone_bytes_as_chunk */ 
{
	/*
	 * orig=NULL; size=0 -> NULL
	 * orig=PTR; size=0 -> new PTR (for instance a shunk with PTR = "")
	 * orig=PTR; size>0 -> new PTR
	 */
	return chunk2(clone_bytes(bytes, sizeof_bytes, name), sizeof_bytes);
}

const char *enum_showb(enum_names *ed, unsigned long val, struct esb_buf *b) /* <=== enum_showb */ 
{
	const char *p = enum_name(ed, val);

	if (p == NULL) {
		snprintf(b->buf, sizeof(b->buf), "%lu??", val);
		p = b->buf;
	}
	return p;
}

const char *bitnamesof(const char *const table[], lset_t val) /* <=== bitnamesof */ 
{
	static char bitnamesbuf[8192]; /* I hope that it is big enough! */

	return bitnamesofb(table, val, bitnamesbuf, sizeof(bitnamesbuf));
}

struct logger cur_logger(void) /* <=== cur_logger */ 
{
	passert(in_main_thread());

	if (cur_state != NULL) {
		struct logger logger = *(cur_state->st_logger);
		logger.global_whackfd = whack_log_fd;
		return logger;
	}

	if (cur_connection != NULL) {
		return CONNECTION_LOGGER(cur_connection, whack_log_fd);
	}

	if (endpoint_type(&cur_from) != NULL) {
		return FROM_LOGGER(&cur_from);
	}

	return GLOBAL_LOGGER(whack_log_fd);
};

void log_message(lset_t rc_flags, const struct logger *log, /* <=== log_message */ 
		 const char *format, ...)
{
	va_list ap;
	va_start(ap, format);
	broadcast(rc_flags, log, format, ap);
	va_end(ap);
}

const char *enum_name(enum_names *ed, unsigned long val) /* <=== enum_name */ 
{
	enum_names  *p;

	for (p = ed; p != NULL; p = p->en_next_range) {
		passert(p->en_last - p->en_first + 1 == p->en_checklen);
		if (p->en_first <= val && val <= p->en_last)
			return p->en_names[val - p->en_first];
	}

	return NULL;
}

void init_pbs(pb_stream *pbs, uint8_t *start, size_t len, const char *name) /* <=== init_pbs */ 
{
	*pbs = (pb_stream) {
		/* .container = NULL, */
		/* .desc = NULL, */
		.name = name,
		.start = start,
		.cur = start,
		.roof = start + len,
		/* .lenfld = NULL, */
		/* .lenfld_desc = NULL, */
		/* .previous_np = NULL, */
		/* .previous_npc.fp = NULL, */
		/* .previous_np_struct = NULL, */
	};
}

bool testset(const char *const table[], lset_t val) /* <=== testset */ 
{
	lset_t bit;
	const char *const *tp;

	for (tp = table, bit = 01; val != 0; bit <<= 1, tp++) {
		const char *n = *tp;

		if (n == NULL || ((val & bit) && *n == '\0'))
			return false;

		val &= ~bit;
	}
	return true;
}

